      if (node) node.focus();
      return;
    }
    setSubmitted(true);
  }

  return (
    <form noValidate onSubmit={handleSubmit} aria-describedby="form-instructions">
      <p id="form-instructions" className="required-legend">
        Fields marked with <span className="req-mark" aria-hidden="true">*</span>
        <span> are required.</span>
      </p>

      <FormField
        id="fullName"
        label="Full name"
        type="text"
        required
        autoComplete="name"
        value={values.fullName}
        error={errors.fullName}
        onChange={handleChange("fullName")}
        onBlur={handleBlur("fullName")}
        inputRef={refs.fullName}
      />

      <FormField
        id="email"
        label="Email address"
        type="email"
        required
        autoComplete="email"
        inputMode="email"
        value={values.email}
        error={errors.email}
        onChange={handleChange("email")}
        onBlur={handleBlur("email")}
        inputRef={refs.email}
      />

      <FormField
        id="phone"
        label="Phone number"
        type="tel"
        required={false}
        autoComplete="tel"
        inputMode="tel"
        value={values.phone}
        error={errors.phone}
        helperId="phone-help"
        helperText="Include country code if outside the US, e.g. +1 (555) 123-4567."
        onChange={handleChange("phone")}
        onBlur={handleBlur("phone")}
        inputRef={refs.phone}
      />

      <div className="actions">
        <button type="submit">Send message</button>
      </div>

      <div
        className={`status success${submitted ? " is-visible" : ""}`}
        role="status"
        aria-live="polite"
      >
        {submitted ? "Thanks! Your message has been sent. We'll be in touch soon." : ""}
      </div>
    </form>
  );
}

function App() {
  return (
    <div className="card">
      <header className="intro">
        <h1>Contact support</h1>
        <p>Send us a message and our team will respond within one business day.</p>
      </header>
      <ContactForm />
    </div>
  );
}

