+    <div className={`form-field${error ? " has-error" : ""}`}>
+      <label htmlFor={id}>
+        {label}
+        {required ? (
+          <span className="req-mark" aria-hidden="true">*</span>
+        ) : (
+          <span className="optional"> (optional)</span>
+        )}
+      </label>
+      <input
+        id={id}
+        name={id}
+        type={type}
+        value={value}
+        required={required || undefined}
+        autoComplete={autoComplete}
+        inputMode={inputMode}
+        aria-invalid={error ? "true" : "false"}
+        aria-describedby={describedBy}
+        onChange={onChange}
+        onBlur={onBlur}
+        ref={inputRef}
+      />
+      {helperText && (
+        <span id={helperId} className="helper">{helperText}</span>
+      )}
+      <span id={errorId} className="error-message" role={error ? "alert" : undefined}>
+        {error ? `Error: ${error}` : ""}
+      </span>
+    </div>
+  );
+}
+
+function ContactForm() {
+  const [values, setValues] = useState({ fullName: "", email: "", phone: "" });
+  const [errors, setErrors] = useState({});
+  const [submitted, setSubmitted] = useState(false);
+
+  const refs = {
+    fullName: useRef(null),
+    email: useRef(null),
+    phone: useRef(null),
+  };
+
+  function validateField(name, value) {
+    const v = value.trim();
+    if (name === "fullName") {
+      if (!v) return "Enter your full name.";
+      return "";
+    }
+    if (name === "email") {
+      if (!v) return "Enter your email address.";
+      if (!EMAIL_RE.test(v)) return "Enter a valid email like name@example.com.";
+      return "";
+    }
+    if (name === "phone") {
+      if (!v) return "";
+      if (!PHONE_RE.test(v)) return "Enter a valid phone number, e.g. +1 (555) 123-4567.";
+      return "";
+    }
+    return "";
+  }
+
+  function validateAll(vals) {
+    return {
+      fullName: validateField("fullName", vals.fullName),
+      email: validateField("email", vals.email),
+      phone: validateField("phone", vals.phone),
+    };
+  }
+
+  function handleChange(name) {
+    return (e) => {
+      const next = { ...values, [name]: e.target.value };
+      setValues(next);
+      // If field already has an error, re-validate as user types so the message updates.
+      if (errors[name]) {
+        setErrors({ ...errors, [name]: validateField(name, e.target.value) });
+      }
+    };
+  }
+
+  function handleBlur(name) {
+    return () => {
+      setErrors((prev) => ({ ...prev, [name]: validateField(name, values[name]) }));
+    };
+  }
+
+  function handleSubmit(e) {
+    e.preventDefault();
+    setSubmitted(false);
+    const newErrors = validateAll(values);
+    setErrors(newErrors);
+    const order = ["fullName", "email", "phone"];
+    const firstInvalid = order.find((k) => newErrors[k]);
+    if (firstInvalid) {
+      const node = refs[firstInvalid].current;
+      if (node) node.focus();
+      return;
+    }
+    setSubmitted(true);
+  }
+
+  return (
+    <form noValidate onSubmit={handleSubmit} aria-describedby="form-instructions">
+      <p id="form-instructions" className="required-legend">
+        Fields marked with <span className="req-mark" aria-hidden="true">*</span>
+        <span> are required.</span>
+      </p>
+
+      <FormField
+        id="fullName"
+        label="Full name"
+        type="text"
+        required
+        autoComplete="name"
+        value={values.fullName}
+        error={errors.fullName}
+        onChange={handleChange("fullName")}
+        onBlur={handleBlur("fullName")}
+        inputRef={refs.fullName}
+      />
+
+      <FormField
+        id="email"
+        label="Email address"
+        type="email"
+        required
+        autoComplete="email"
+        inputMode="email"
+        value={values.email}
+        error={errors.email}
+        onChange={handleChange("email")}
+        onBlur={handleBlur("email")}
+        inputRef={refs.email}
+      />
+
+      <FormField
+        id="phone"
+        label="Phone number"
+        type="tel"
+        required={false}
+        autoComplete="tel"
+        inputMode="tel"
+        value={values.phone}
+        error={errors.phone}
+        helperId="phone-help"
+        helperText="Include country code if outside the US, e.g. +1 (555) 123-4567."
+        onChange={handleChange("phone")}
+        onBlur={handleBlur("phone")}
+        inputRef={refs.phone}
+      />
+
+      <div className="actions">
+        <button type="submit">Send message</button>
+      </div>
+
+      <div
+        className={`status success${submitted ? " is-visible" : ""}`}
+        role="status"
+        aria-live="polite"
+      >
+        {submitted ? "Thanks! Your message has been sent. We'll be in touch soon." : ""}
+      </div>
+    </form>
+  );
+}
+
+function App() {
+  return (
+    <div className="card">
+      <header className="intro">
+        <h1>Contact support</h1>
+        <p>Send us a message and our team will respond within one business day.</p>
+      </header>
+      <ContactForm />
+    </div>
+  );
+}
+
+ReactDOM.createRoot(document.getElementById("root")).render(<App />);
+
')

